app.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav)return page(nav.dataset.nav);const el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el);});
overlay.addEventListener('click',e=>{const rhythmButton=e.target.closest('[data-rhythm-lane]');if(rhythmButton){if(e.detail===0&&game)act(game.held[Number(rhythmButton.dataset.rhythmLane)]?'release':'beat',{i:Number(rhythmButton.dataset.rhythmLane)});return;}const el=e.target.closest('[data-action]');if(el)return action(el.dataset.action,el);const g=e.target.closest('[data-g]');if(g&&!g.disabled&&!['slider','offset'].includes(g.dataset.g))act(g.dataset.g,payload(g));});
function payload(el){return Object.fromEntries(Object.entries(el.dataset).filter(([k])=>!['g','drag','drop','upgradeAction'].includes(k)).map(([k,v])=>[k,['i','value','row','start','board'].includes(k)?Number(v):v]));}
overlay.addEventListener('input',e=>{if(e.target.matches('[data-g="slider"],[data-g="offset"]')){e.target.closest('label').querySelector('output').textContent=e.target.value+(e.target.dataset.g==='offset'?'°':'');act(e.target.dataset.g,{...payload(e.target),value:Number(e.target.value)});}});
