function tracePoint(e){const svg=$('#trace-board');if(!svg||!game)return;const rect=svg.getBoundingClientRect();act('trace',{x:(e.clientX-rect.left)/rect.width*600,y:(e.clientY-rect.top)/rect.height*240});}
function panPoint(e){const track=$('[data-pan-track]');if(!track)return;const rect=track.getBoundingClientRect();act('pan-pointer',{position:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width))});}
function trackingPoint(e){const track=$('[data-tracking]');if(!track||!game)return;const rect=track.getBoundingClientRect();act('move',{position:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width))});}
let touchDrag=null;const rhythmPointers=new Map();
overlay.addEventListener('pointerdown',e=>{if(!game||paused)return;held=true;const lane=e.target.closest('[data-rhythm-lane]');if(lane){const i=Number(lane.dataset.rhythmLane);if(e.pointerType==='mouse'&&game.held[i])act('release',{i});else act('beat',{i});if(e.pointerType!=='mouse')rhythmPointers.set(e.pointerId,i);e.preventDefault();}if(e.target.closest('[data-pan-track]'))panPoint(e);const trace=e.target.closest('#trace-board');if(trace){traceActive=true;trace.setPointerCapture?.(e.pointerId);tracePoint(e);e.preventDefault();}if(e.target.closest('[data-tracking]')){trackingPoint(e);e.preventDefault();}const pulse=e.target.closest('[data-hold="pulse"]');if(pulse&&!pulse.disabled){pulseStarted=game.elapsed;pulse.setPointerCapture?.(e.pointerId);e.preventDefault();}const piece=e.target.closest('[data-drag]');if(piece&&e.pointerType!=='mouse'){touchDrag={x:e.clientX,y:e.clientY,i:Number(piece.dataset.drag)};act('select',{i:touchDrag.i});}});
overlay.addEventListener('pointermove',e=>{if(!game||paused)return;if(held&&e.target.closest('[data-pan-track]'))panPoint(e);if(traceActive){for(const p of [...(e.getCoalescedEvents?.()||[]),e])tracePoint(p);e.preventDefault();}if(held&&e.target.closest('[data-tracking]'))trackingPoint(e);});
window.addEventListener('pointerup',e=>{if(game&&[69,77].includes(game.id)&&!paused&&rhythmPointers.has(e.pointerId)){act('release',{i:rhythmPointers.get(e.pointerId)});rhythmPointers.delete(e.pointerId);}if(pulseStarted!==null&&game&&!paused){const duration=game.elapsed-pulseStarted;pulseStarted=null;act('pulse',{duration});}if(touchDrag&&Math.hypot(e.clientX-touchDrag.x,e.clientY-touchDrag.y)>8){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');if(target)act(target.dataset.drop,payload(target));}touchDrag=null;traceActive=false;held=false;});
window.addEventListener('pointercancel',e=>{if(rhythmPointers.has(e.pointerId)){act('release',{i:rhythmPointers.get(e.pointerId)});rhythmPointers.delete(e.pointerId);}held=false;traceActive=false;touchDrag=null;pulseStarted=null;});
overlay.addEventListener('dragstart',e=>{const piece=e.target.closest('[data-drag]');if(!piece||paused||!game){e.preventDefault();return;}dragging=true;act('select',{i:Number(piece.dataset.drag)});e.dataTransfer.setData('text/plain',piece.dataset.drag);e.dataTransfer.effectAllowed='move';});
overlay.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault();});
overlay.addEventListener('drop',e=>{e.preventDefault();const target=e.target.closest('[data-drop]');if(target&&dragging)act(target.dataset.drop,payload(target));dragging=false;held=false;paint(true);});
overlay.addEventListener('dragend',()=>{dragging=false;held=false;});
document.addEventListener('keydown',e=>{if(!overlay.firstElementChild)return;if(e.key==='Tab'){const items=$$('button:not([disabled]),input,select,summary,[tabindex="0"]',overlay).filter(el=>el.getClientRects().length&&!el.closest('[inert]'));const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Escape'){e.preventDefault();if(game)setPaused(!paused);else if(attempt){action('abandon');}else close();return;}if(!game||paused||(e.repeat&&![12,19,26,33,39].includes(game.id))||e.target.matches('input,select')||e.target.closest('[data-action]'))return;const id=game.id,key=e.key.toLowerCase();if(id>=101&&id<=107&&['arrowleft','arrowright',' '].includes(key)){e.preventDefault();act(key===' '?'shake':'nudge',{value:key==='arrowleft'?-1:1});return;}if([60,69,77].includes(id)&&/^[1-6]$/.test(key)){e.preventDefault();act('beat',{i:Number(key)-1});return;}if(id===53&&e.code==='Space'){e.preventDefault();act('lock');return;}if(id===5&&e.code==='Space'){e.preventDefault();if(game.phase==='input'&&pulseStarted===null)pulseStarted=game.elapsed;return;}if([1,16,52].includes(id)&&e.code==='Space'){e.preventDefault();act(id===1?'hit':id===16?'beat':'convert',{i:0});return;}if(id===37&&['a','d','arrowleft','arrowright'].includes(key)){e.preventDefault();act('beat',{i:['a','arrowleft'].includes(key)?0:1});return;}if(id===12&&key.startsWith('arrow')){e.preventDefault();act('trace-key',{i:{arrowup:0,arrowright:1,arrowdown:2,arrowleft:3}[key]});return;}if([19,26,33,39].includes(id)&&['arrowleft','arrowright','arrowup','arrowdown'].includes(key)){e.preventDefault();const positive=['arrowright','arrowup'].includes(key);act(id===19?'push':id===26?(positive?'up':'down'):id===33?'move':'impulse',{value:positive?1:-1});return;}if(/^[1-9]$/.test(key)){const i=Number(key)-1;if(id===20||id===46){e.preventDefault();act('symbol',{i});}else if([2,11,17,28,40,50].includes(id)){const piece=$(`[data-drag="${i}"]`);if(piece){e.preventDefault();act('select',{i});}}}});
document.addEventListener('keyup',e=>{if(game&&[69,77].includes(game.id)&&/^[1-5]$/.test(e.key)&&!paused){act('release',{i:Number(e.key)-1});return;}if(e.code==='Space'&&game?.id===5&&pulseStarted!==null&&!paused){e.preventDefault();const duration=game.elapsed-pulseStarted;pulseStarted=null;act('pulse',{duration});}});
document.addEventListener('visibilitychange',()=>{lastFrame=performance.now();if(document.hidden&&game)setPaused(true);else if(!document.hidden){if(!online.active&&E.background(state))save();}});
window.addEventListener('blur',()=>{if(game)setPaused(true);});
window.addEventListener('storage',event=>{if(online.active||event.key!==E.SAVE_KEY||!event.newValue)return;try{state=E.load(localStorage);if(attempt)close();else render();toast('Progress synchronized from another game tab.');}catch{toast('Another tab updated the save, but it could not be read. Your current game is preserved.');}});
window.addEventListener('beforeunload',save);
function frame(now){const dt=Math.min(.04,Math.max(0,(now-(lastFrame||now))/1000));lastFrame=now;if(game&&!paused&&!document.hidden){if(online.active&&dt>0)recording.push(['t',dt]);tickGame(game,dt);if(online.active&&game.id===1&&!game.duration&&recording.length>12000&&!checkpointPending){const events=recording.splice(0);checkpointPending=online.command('checkpoint',{attempt:attempt.id,index:attempt.index,events}).then(data=>{applyCloud(data);attempt=data.attempt;}).catch(error=>{checkpointRecovery=events.length;recording.unshift(...events);if(game)setPaused(true);toast(error.message+' Resume after reconnecting.');throw error;}).finally(()=>{checkpointPending=null;});checkpointPending.catch(()=>{});}if(!checkOutcome()&&now-lastPaint>65){paint();lastPaint=now;}}requestAnimationFrame(frame);}
let lastBeat=Date.now(),ticks=0;
setInterval(()=>{const now=Date.now();if(!online.active&&!document.hidden)state.stats.playtime+=Math.min(2,(now-lastBeat)/1000);lastBeat=now;ticks++;const previous=state.market.quote,changed=!online.active&&E.background(state,now);if(changed){save();if(!attempt&&['market','smelting','dashboard','inventory'].includes(ui.page)&&!document.activeElement?.matches('input,select'))render();if(previous<state.market.alert&&state.market.quote>=state.market.alert&&state.market.upgrades.includes('alerts'))toast('Price alert: copper reached $'+(state.market.quote/10000).toFixed(4)+'/g.');}else if(ticks%30===0)save();$$('[data-countdown]').forEach(el=>el.textContent=Math.max(0,Math.ceil((state.market.next-now-(state.market.global?(online.clockOffset||0):0))/1000))+'s');$$('[data-refresh-cooldown]').forEach(el=>el.textContent=Math.max(0,Math.ceil((state.market.refreshAt-now)/1000))+'s cooldown');for(const job of state.furnace.jobs){const timer=$(`[data-job-time="${job.id}"]`),bar=$(`[data-job-progress="${job.id}"]`),button=$(`[data-action="furnace-collect"][data-id="${job.id}"]`);if(timer)timer.textContent=job.ends<=now?'Ready to collect':Math.ceil((job.ends-now)/1000)+'s remaining';if(bar)bar.style.width=Math.min(100,(now-job.started)/(job.ends-job.started)*100)+'%';if(button&&job.ends<=now){button.disabled=false;button.textContent='Collect ingots';}}},1000);
E.background(state);E.checkAchievements(state);save();const initialHash=location.hash.slice(1);if(NAV.some(n=>n[0]===initialHash))ui.page=initialHash;render();requestAnimationFrame(frame);

function applyCloud(data){if(data.slot&&data.slot!==online.slot)throw Error('Save slot mismatch. Refresh your selected workshop.');online.classification=data.classification||online.classification;if(data.admin)online.admin=data.admin;if(!online.active||online.session?.user.id!==online.activeUserId)throw Error('Your sign-in changed. The local workshop is preserved.');state=E.expansionDefaults(data.state);state.market.global=true;state.goldMarket.history=online.goldMarket?.history||[];if(online.goldMarket)Object.assign(state.goldMarket,online.goldMarket);state.market.history=online.market?.history||[];if(online.market&&online.market.next>=state.market.next)Object.assign(state.market,online.market);online.revision=data.revision;online.attempt=data.attempt;online.lastSync=Date.now();}
async function enterOnline(){if(attempt)throw Error('Leave your current attempt before switching workshops.');if(!online.active){save();guestState=state;}if(!online.active)online.slot=online.admin?.owner?online.admin.preferredSlot||'main':'main';const data=await online.load();online.active=true;online.activeUserId=online.session.user.id;try{localStorage.setItem('copper-online-mode',online.session.user.id);}catch{}applyCloud(data);attempt=null;render();toast(online.slot==='debug'?'Debug Workshop loaded. Its economy is isolated.':'Main Workshop loaded from your account.');}
function returnLocal(){try{localStorage.removeItem('copper-online-mode');}catch{}online.active=false;state=E.load(localStorage);if(online.market)Object.assign(state.market,online.market);guestState=state;attempt=null;game=null;render();}
online.onSignOut=()=>{if(online.active)returnLocal();else if(state!==guestState){state=guestState;attempt=null;game=null;overlay.innerHTML='';document.body.classList.remove('modal-open');app.inert=false;render();}};
async function verifyOutcome(finished){unsavedOutcome=finished;
 verifying=true;modal('<div class="result-screen"><h2 id="modal-title">Saving your recovery…</h2><p>Your challenge is being checked by the online workshop.</p></div>','result-modal');
 try{
  if(checkpointPending)await checkpointPending;
  const failed=finished.status==='failed';const data=await online.command(failed?'fail':'stage',failed?{}:{attempt:attempt.id,index:attempt.index,events:recording});applyCloud(data);attempt=data.attempt;verifying=false;
  if(failed){verifiedFailure=true;game=finished;checkOutcome();verifiedFailure=false;}
  else if(attempt.status==='complete')complete(data.result);
  else modal(challengeHeader()+'<div class="challenge-intro"><div class="challenge-icon success-icon">'+icon('check')+'</div><h2 id="modal-title">One step closer.</h2><p>Stage '+attempt.index+' verified and saved. Every remaining challenge must be completed.</p>'+primary('next-stage','Continue to stage '+(attempt.index+1))+'</div>','game-modal');
 }catch(error){verifying=false;modal('<div class="result-screen"><h2 id="modal-title">Recovery not yet saved.</h2><p>'+escapeHTML(error.message)+'</p><p>Your local game and original item are preserved. Retry the same save after reconnecting, or refresh your cloud workshop.</p><button class="button primary" data-online="retry-stage">Retry save</button><button class="button secondary" data-online="refresh-stage">Refresh workshop</button></div>','result-modal');}
}
const cloudMutations=new Set(['refund-essence','compression','essence','gold-equipment','gold-research','gold-claim','confirm-ascension','gold-buy','gold-sell','purchase','tool','market-upgrade','sell','sell-custom','market-refresh','set-alert','limit-order','cancel-order','craft','research','roll','equip-aura','equip-and-close','confirm-rebirth','prestige','furnace-start','furnace-collect','furnace-upgrade','sell-ingots','buy-automation','auto-toggle','buy-refining','refine','sell-refined','refining-research','accept-contract','claim-contract','setting','sound','furnace-challenge']);
async function cloudAction(name,el){
 if(!cloudMutations.has(name))return false;
 const p={id:el?.dataset.id};if(el?.dataset.rank)p.rank=Number(el.dataset.rank);let command=name;
 if(name==='sell'||name==='sell-custom'){command='trade';p.side='sell';p.quality=ui.quality;p.quote=state.market.quote;p.amount=(name==='sell'?state.copper[ui.quality]*BigInt(el.dataset.percent)/100n:parseCopper($('#sell-amount').value,$('#sell-unit').value)).toString();}
 if(name==='gold-buy'||name==='gold-sell'){command='trade';p.asset='gold';p.side=name==='gold-buy'?'buy':'sell';p.quote=state.goldMarket.quote;p.amount=$('#gold-trade-amount').value;}
 if(name==='furnace-start')p.amount=parseCopper($('#furnace-amount').value,'kg').toString();
 if(name==='set-alert')p.quote=Math.round(Number($('#price-alert').value)*10000);
 if(name==='limit-order'){p.amount=parseCopper($('#sell-amount').value,$('#sell-unit').value).toString();p.quote=Math.round(Number($('#limit-price').value)*10000);p.quality=ui.quality;}
 if(name==='furnace-challenge'){command='begin';p.mode='furnace';p.device=1;}
 const data=await online.command(command,p);applyCloud(data);
 if(name==='furnace-challenge'){attempt=data.attempt;briefing();return true;}
 if(name==='refund-essence'){close();page('ascension');return true;}if(name==='confirm-ascension'){close();page('ascension');return true;}if(name==='confirm-rebirth'||name==='equip-and-close'){close();if(name==='confirm-rebirth')page('rebirth');}
 else render();
 if(name==='roll'){const aura=data.result;modal('<div class="result-screen"><h2 id="modal-title">'+escapeHTML(aura.name)+'</h2><p>'+aura.luck.toFixed(2)+'× equipped luck.</p>'+primary('equip-and-close','Equip this aura','data-id="'+aura.id+'"')+backButton()+'</div>','result-modal');}
 else toast(data.result?.message||(data.result?.proceeds?'Sold for '+money(data.result.proceeds)+'.':'Saved to your online workshop.'));return true;
}
async function onlineAction(name){
 const value=id=>document.getElementById(id)?.value||'';
 try{
 if(!online.client)throw Error(online.error||'The online service is still connecting.');
 switch(name){
 case 'signin':await online.signIn(value('account-email'),value('account-password'));await enterOnline();break;
 case 'signup':{const ready=await online.signUp(value('signup-email'),value('signup-password'),value('signup-username'));if(ready)await enterOnline();else{render();toast('Check your email to confirm your account, then sign in.');}break;}
 case 'reset':await online.reset(value('account-email'));toast('If that email is registered, a reset link has been sent.');break;
 case 'password':await online.password(value('new-password'));render();toast('Password updated.');break;
 case 'online':await enterOnline();break;
 case 'local':if(attempt)throw Error('Leave your attempt first.');returnLocal();toast('Your original local workshop is ready.');break;
 case 'signout':if(attempt)throw Error('Leave your attempt first.');if(online.active)returnLocal();await online.signOut();render();break;
 case 'backup':await online.backup(E.encode(online.active?guestState:state));toast('Your local workshop is backed up to this account.');break;
 case 'restore':{const restored=await online.restore();modal('<div class="result-screen"><h2 id="modal-title">Restore your local workshop?</h2><p>Rebirth '+restored.rebirth+' · Level '+E.level(restored)+' · '+copper(E.totalCopper(restored))+'. This replaces only your local workshop. A recovery copy is kept.</p><button class="button primary" data-online="confirm-restore">Restore local backup</button><button class="button secondary" data-action="close">Keep current game</button></div>','result-modal');online.restoreCandidate=restored;break;}
 case 'confirm-restore':{if(!online.restoreCandidate)throw Error('Review a backup first.');localStorage.setItem(E.SAVE_KEY+'-before-cloud-restore',localStorage.getItem(E.SAVE_KEY)||E.encode(guestState));guestState=online.restoreCandidate;E.persist(localStorage,guestState);online.restoreCandidate=null;returnLocal();close();toast('Local workshop restored. Your verified online save is unchanged.');break;}
 case 'boards':await online.pollRankings();render();break;
 case 'buy':{if(!online.active)throw Error('Continue your online workshop first.');const data=await online.command('trade',{side:'buy',quality:0,amount:parseCopper(value('buy-copper'),'g').toString(),quote:state.market.quote});applyCloud(data);render();toast('Copper purchased and saved.');break;}
 case 'retry':{const data=await online.retry();if(online.active)applyCloud(data);render();toast('Pending action saved.');break;}
 case 'retry-clock':case 'retry-stage':{const data=await online.retry();applyCloud(data);attempt=data.attempt;if(checkpointRecovery){recording.splice(0,checkpointRecovery);checkpointRecovery=0;if(game){setPaused(false);break;}if(unsavedOutcome){verifyOutcome(unsavedOutcome);break;}}if(attempt?.status==='complete')complete(data.result);else if(attempt?.status==='briefing')briefing();else close();break;}
 case 'refresh-stage':attempt=null;game=null;close();await enterOnline();page('account');break;
 }
 }catch(error){toast(error.message);}
}
document.addEventListener('click',event=>{const control=event.target.closest('[data-online]');if(control)onlineAction(control.dataset.online);if(event.target.closest('[data-music-toggle]')){music.toggle();render();}});
document.addEventListener('input',event=>{if(event.target.matches('[data-music-volume]'))music.volume(Number(event.target.value));});
let onlinePolling=false,lastCloudPoll=0,lastBoardPoll=0,marketPollTimer;

async function pollOnline(){ownerPanel?.tick();if(document.hidden||onlinePolling||!online.client)return;onlinePolling=true;try{
 const previous=state.market.quote,market=await online.pollMarket(ui.page==='market',ui.page==='gold');Object.assign(state.market,market);if(online.goldMarket)Object.assign(state.goldMarket,online.goldMarket);$('[data-market-price]').forEach(el=>el.textContent=(state.market.quote/10000).toFixed(4));$('[data-gold-price]').forEach(el=>el.textContent=(state.goldMarket.quote/10000).toFixed(4));const sale=$('[data-sale-preview]');if(sale)sale.textContent=money(E.saleValue(state.copper[ui.quality],state.market.quote,ui.quality));if(!attempt){const copperChart=$('.market-full .market-chart')||$('.market-preview .market-chart');if(copperChart)copperChart.outerHTML=chart(state,ui.page==='market');const goldChartHost=$('[data-gold-chart]');if(goldChartHost)syncHTML(goldChartHost,goldChart(state.goldMarket));}
 if(previous<state.market.alert&&market.quote>=state.market.alert&&state.market.upgrades.includes('alerts'))toast('Shared price alert: copper reached '+String.fromCharCode(36)+(market.quote/10000).toFixed(4)+'/g.');
 if(online.active&&!attempt&&!online.busy&&!online.pending&&!ownerPanel?.confirmation&&Date.now()-lastCloudPoll>=20000){const data=await online.command('heartbeat');applyCloud(data);lastCloudPoll=Date.now();}
 if(online.admin?.owner&&ownerPanel?.open&&!online.busy)await online.adminStatus();ownerPanel?.render();if(ui.page==='leaderboards'&&Date.now()-lastBoardPoll>=30000){await online.pollRankings();lastBoardPoll=Date.now();}
 if(!attempt&&!document.activeElement?.matches('input,select')&&!ownerPanel?.root.contains(document.activeElement)&&['market','gold','ascension','dashboard','account','leaderboards'].includes(ui.page))render();
 }catch(error){online.error=error.message;if(online.active&&ui.page==='account'&&!document.activeElement?.matches('input'))render();}finally{onlinePolling=false;clearTimeout(marketPollTimer);const untilTick=(online.market?.next||0)-Date.now()-(online.clockOffset||0);marketPollTimer=setTimeout(pollOnline,untilTick>0?Math.min(10000,untilTick+150):10000);}}
ownerPanel=new OwnerAdminPanel({online,state:()=>state,attempt:()=>attempt||online.pending||verifying,pause:()=>{if(game)setPaused(true);},apply:applyCloud,render,enter:enterOnline,poll:pollOnline});
setInterval(()=>ownerPanel.tick(),1000);
online.init().then(async()=>{try{if(online.session&&localStorage.getItem('copper-online-mode')===online.session.user.id)await enterOnline();}catch(error){online.error=error.message;}await pollOnline();if(!document.activeElement?.matches('input,select'))render();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollOnline();});
